import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVat } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid inputs', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.customerId, 'C-002');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 1);
  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 10,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 0,
  });
});

